const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');}));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
function calculate(){const values={};['revenue','ota','fee','shift'].forEach(id=>{values[id]=Number(document.getElementById(id).value);document.getElementById(id+'-out').textContent=id==='revenue'?money(values[id]):values[id]+'%';});const result=values.revenue*values.ota/100*values.fee/100*values.shift/100;document.getElementById('saving').textContent=money(result);document.getElementById('calculation').textContent=`${money(values.revenue)} × ${values.ota}% OTA share × ${values.shift}% shifted × ${values.fee}% commission`;}
document.querySelectorAll('input[type=range]').forEach(input=>input.addEventListener('input',calculate));calculate();
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#goal').value=a.dataset.service;}));
document.querySelector('#audit-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);const message=`Hello GrowGuest, I’d like a free growth audit.\nName: ${data.get('name').trim()}\nProperty: ${data.get('property').trim()}\nType: ${data.get('type')}\nWebsite / listing: ${data.get('website').trim()||'Not provided'}\nMain goal: ${data.get('goal')}`;window.open('https://wa.me/918956907343?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');});
